    'ui.ph_newcomer_coupon' => $t('e.g. New-member off', '例如 新会员立减', 'z. B. Neukundenrabatt', 'p. ej. Descuento nuevo socio', 'ex. Remise nouveau membre', '예: 신규 회원 할인', 'ex. Desconto novo membro', '例: 新規会員割引'),
